SELECT
	ADMIN_ID AS adminId,
	ADMIN_PWD AS adminPwd
FROM TBL_ADMIN
WHERE ADMIN_ID = #{adminId}
AND ADMIN_PWD = #{adminPwd}

mapper.update:
UPDATE STORE S
JOIN STORE_USER SU ON S.S_USER_ID = SU.S_USER_ID
SET 
    SU.U_STATUS = 'REJ'
WHERE S.STORE_NO = #{storeNo}
AND SU.S_USER_ID = #{sUserId};

UPDATE REVIEW_REPORT
SET REP_STATUS = 'REJ'
WHERE REPORT_NO = #{reportNo}

UPDATE REVIEW_REPORT
SET REP_STATUS = 'ACC'
WHERE REPORT_NO = #{reportNo}

mapper.select:
SELECT COUNT(*)
FROM REVIEW_FILE
WHERE REVIEW_NO = #{reviewNo}
